def solve(grid):
    n = len(grid)
    m = len(grid[0]) if n else 0

    # count non‑zero colours
    cnt = {}
    for r in grid:
        for v in r:
            if v:
                cnt[v] = cnt.get(v, 0) + 1

    if len(cnt) < 2:
        return grid

    # most frequent = A, less frequent = B
    A = max(cnt, key=cnt.get)
    B = min(cnt, key=cnt.get)

    # bounding boxes for A and B
    r_min_A = r_max_A = c_min_A = c_max_A = None
    r_min_B = r_max_B = c_min_B = c_max_B = None

    for i in range(n):
        for j in range(m):
            v = grid[i][j]
            if v == A:
                if r_min_A is None:
                    r_min_A = r_max_A = i
                    c_min_A = c_max_A = j
                else:
                    if i < r_min_A: r_min_A = i
                    if i > r_max_A: r_max_A = i
                    if j < c_min_A: c_min_A = j
                    if j > c_max_A: c_max_A = j
            elif v == B:
                if r_min_B is None:
                    r_min_B = r_max_B = i
                    c_min_B = c_max_B = j
                else:
                    if i < r_min_B: r_min_B = i
                    if i > r_max_B: r_max_B = i
                    if j < c_min_B: c_min_B = j
                    if j > c_max_B: c_max_B = j

    # intersection of the two bounding boxes
    r_start = max(r_min_A, r_min_B)
    r_end   = min(r_max_A, r_max_B)
    c_start = max(c_min_A, c_min_B)
    c_end   = min(c_max_A, c_max_B)

    if r_start > r_end or c_start > c_end:
        return grid   # no overlap – nothing to do

    # centre of the intersecting rectangle
    central_row = (r_start + r_end) // 2                     # floor
    central_col = (c_start + c_end + 1) // 2                 # ceil

    height = r_end - r_start + 1

    out = [row[:] for row in grid]

    for i in range(r_start, r_end + 1):
        for j in range(c_start, c_end + 1):
            if grid[i][j] != B:
                continue

            # orthogonal adjacency to colour A
            adj = False
            for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                ni, nj = i + di, j + dj
                if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == A:
                    adj = True
                    break

            # conversion rules
            if adj and (i <= central_row or j <= central_col):
                out[i][j] = A
            elif i == central_row and j <= central_col:
                out[i][j] = A
            elif j == central_col and (height % 2 == 0 or i <= central_row):
                out[i][j] = A
            else:
                out[i][j] = 0

    return out

